export function academicUploadSourceKind(file:Pick<File,'name'|'type'>):'upload'|'pdf'{return /\.pdf$/i.test(file.name)||file.type.toLowerCase()==='application/pdf'?'pdf':'upload'}
export function academicCompanionPdfAllowed(file:Pick<File,'name'>|null):boolean{return Boolean(file&&/\.(?:tex|zip)$/i.test(file.name))}
export function normalizeAcademicWebReference(value:string):string|null{
  const reference=value.trim();if(!reference||/[\r\n]/.test(reference))return null;
  if(/^10\.\d{4,9}\/\S+$/i.test(reference))return reference;
  try{const url=new URL(reference);if(url.protocol!=='https:'||url.username||url.password)return null;return url.toString()}catch{return null}
}

